using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace Veyra.Setup {
 internal sealed class LocalBrowser {public string Exe;public Version Version;}
 internal static class BrowserFinder {
  internal static LocalBrowser Read(string exe){try{Paths.NoLinks(exe);if(!File.Exists(exe))return null;var info=FileVersionInfo.GetVersionInfo(exe);Version v;if(!String.Equals(info.ProductName,"Veyra",StringComparison.OrdinalIgnoreCase)||!Version.TryParse(info.ProductVersion,out v))return null;return new LocalBrowser{Exe=Path.GetFullPath(exe),Version=new Version(v.Major,v.Minor,Math.Max(0,v.Build))};}catch(Exception){return null;}}
  internal static LocalBrowser Best(IEnumerable<string> paths){return paths.Distinct(StringComparer.OrdinalIgnoreCase).Select(Read).Where(x=>x!=null).OrderByDescending(x=>x.Version).FirstOrDefault();}
  internal static LocalBrowser Find(){var paths=new List<string>();var root=Layout.Current();paths.Add(root.Exe);string own=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);paths.Add(Path.Combine(own,"Veyra.exe"));paths.Add(Path.Combine(own,"app","Veyra.exe"));
   foreach(string parent in new[]{Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"OneDrive","Документи"),root.Root})try{
    if(!Directory.Exists(parent))continue;Paths.NoLinks(parent);foreach(string folder in Directory.EnumerateDirectories(parent).Where(d=>Path.GetFileName(d).StartsWith("Veyra",StringComparison.OrdinalIgnoreCase)||Path.GetFileName(d).StartsWith("versions",StringComparison.OrdinalIgnoreCase)).Take(50)){
     paths.Add(Path.Combine(folder,"Veyra.exe"));paths.Add(Path.Combine(folder,"app","Veyra.exe"));Paths.NoLinks(folder);foreach(string dist in Directory.EnumerateDirectories(folder,"dist*").Take(50))paths.Add(Path.Combine(dist,"Veyra-win32-x64","Veyra.exe"));
    }
   }catch(Exception){}return Best(paths);
  }
 }
 internal sealed class LauncherForm:Form {
  readonly Label status=new Label();readonly Button start=new Button(),update=new Button();readonly ProgressBarView progress=new ProgressBarView();readonly CancellationTokenSource stop=new CancellationTokenSource();LocalBrowser local;bool launching;
  public LauncherForm(){Text="Veyra Launcher";ClientSize=new Size(650,370);FormBorderStyle=FormBorderStyle.None;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(20,17,27);ForeColor=Color.FromArgb(238,232,248);Font=new Font("Segoe UI",10);Controls.Add(new Brand{Location=new Point(30,22),Size=new Size(64,64)});Controls.Add(new Label{Text="Veyra",Font=new Font("Segoe UI",24,FontStyle.Bold),Location=new Point(106,18),AutoSize=true});Controls.Add(new Label{Text="by Nexaridev",Location=new Point(110,65),AutoSize=true});Controls.Add(new Label{Text="Готовим браузер к запуску",Font=new Font("Segoe UI",18,FontStyle.Bold),Location=new Point(36,124),AutoSize=true});status.SetBounds(38,177,570,65);status.Text="Ищем установленную версию…";Controls.Add(status);var close=new Button{Text="Закрыть",Location=new Point(548,25),Size=new Size(78,30),FlatStyle=FlatStyle.Flat,BackColor=BackColor,ForeColor=ForeColor};close.Click+=delegate{Close();};Controls.Add(close);progress.SetBounds(38,248,574,5);Controls.Add(progress);start.Text="Запустить без обновления";start.SetBounds(38,285,265,42);update.Text="Обновить";update.SetBounds(320,285,292,42);foreach(var b in new[]{start,update}){b.FlatStyle=FlatStyle.Flat;b.BackColor=Color.FromArgb(185,159,252);b.ForeColor=Color.FromArgb(20,17,27);b.Visible=false;Controls.Add(b);}start.Click+=delegate{Launch();};update.Click+=delegate{OpenSetup();};Shown+=async delegate{await Check();};FormClosed+=delegate{stop.Cancel();};}
  async Task Check(){local=BrowserFinder.Find();if(local==null){progress.Value=0;status.Text="Veyra не найдена. Установи браузер в стандартную папку или положи лаунчер рядом с Veyra.exe.";update.Text="Установить Veyra";update.Visible=true;return;}status.Text="Найдена Veyra "+local.Version+". Проверяем обновления…";try{using(var deadline=CancellationTokenSource.CreateLinkedTokenSource(stop.Token))using(var network=new Network()){deadline.CancelAfter(TimeSpan.FromSeconds(8));var release=await network.Latest(deadline.Token);if(IsDisposed||stop.IsCancellationRequested)return;if(new Version(release.Version)>local.Version){progress.Value=0;status.Text="На ПК: "+local.Version+". Доступна версия "+release.Version+". Обновить перед запуском?";start.Visible=update.Visible=true;return;}}}catch(Exception){if(stop.IsCancellationRequested)return;status.Text="Проверка обновлений недоступна. Запускаем установленную версию.";}if(!stop.IsCancellationRequested)Launch();}
  void Launch(){if(launching)return;try{local=BrowserFinder.Find();if(local==null)throw new IOException("Установленная версия больше не найдена.");Process.Start(new ProcessStartInfo(local.Exe){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(local.Exe)});launching=true;Close();}catch(Exception e){status.Text="Не удалось запустить Veyra: "+e.Message;progress.Value=0;update.Text="Переустановить";update.Visible=true;}}
  void OpenSetup(){try{string setup=Veyra.Setup.Layout.Current().SetupExe;Paths.NoLinks(setup);bool standalone=!File.Exists(setup);if(standalone)setup=Assembly.GetExecutingAssembly().Location;Process.Start(new ProcessStartInfo(setup,standalone?"--install":""){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(setup)});Close();}catch(Exception e){status.Text=e.Message;}}
 }
}
